using PromiseHub.Application;

namespace PromiseHub.Infrastructure.Storage;

/// <summary>File storage on the local disk under a root folder (ADR 0050). Keys are generated by the caller and stay inside the root.</summary>
public sealed class LocalFileStore(string rootPath) : IFileStore
{
    private readonly string _root = Path.GetFullPath(rootPath);

    public async Task SaveAsync(string key, Stream content, CancellationToken cancellationToken)
    {
        var path = PathFor(key);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        await using var file = File.Create(path);
        await content.CopyToAsync(file, cancellationToken);
    }

    public Task DeleteAsync(string key, CancellationToken cancellationToken)
    {
        File.Delete(PathFor(key));
        return Task.CompletedTask;
    }

    public Task<bool> ExistsAsync(string key, CancellationToken cancellationToken) => Task.FromResult(File.Exists(PathFor(key)));

    private string PathFor(string key)
    {
        var path = Path.GetFullPath(Path.Combine(_root, key));
        if (!path.StartsWith(_root + Path.DirectorySeparatorChar, StringComparison.Ordinal))
        {
            throw new ArgumentException("The key leaves the storage root.", nameof(key));
        }
        return path;
    }
}
